/* ---- conversation history -------------------------------------------- */

.conv-table th {
  text-align: left;
  padding: 1px 3px;
  color: var(--dim);
  font-weight: normal;
  border-bottom: 1px solid var(--edge);
  white-space: nowrap;
}

.conv-row { cursor: pointer; }
.conv-row:hover { background: #232a34; }

/* The transcript is the one thing on this page where line breaks carry
 * meaning: each turn is a line, and reflowing them runs the two speakers
 * together.
 */
.conv-text {
  margin: 6px 0 4px;
  padding: 6px 8px;
  background: #05070a;
  border: 1px solid var(--edge);
  border-radius: 4px;
  font: inherit;
  white-space: pre-wrap;
  word-break: break-word;
  max-height: 220px;
  overflow: auto;
}

