#!/usr/bin/env python3
"""Remove the browser key store from app.js.

Whole-block deletions by anchor, so a failed match is reported rather than
silently leaving half the feature behind.
"""
import sys

P = ('/home/mi/vela_competition_continue/contest/'
     'contest2026_264_VelaSightsuixingAIzhinengyanjing/app/web_tool/host/'
     'web/app.js')

s = open(P, encoding='utf-8').read()
orig = s

start = s.index("/* ---- key store ---")
end = s.index("/* ---- wiring ---")
block = s[start:end]
if 'keystore' not in block:
    print("FAIL: block between key store and wiring does not look right")
    sys.exit(1)
s = s[:start] + s[end:]

# The wiring for the five deleted controls.
wiring = """  $('btn-key-show').onclick = () => {
    const el = $('llm-key');
    el.type = el.type === 'password' ? 'text' : 'password';
  };
  $('btn-key-save').onclick = keySave;
  $('btn-key-unlock').onclick = keyUnlock;
  $('btn-key-forget').onclick = () => {
    keystore.forget();
    $('key-warn').textContent = '已从本机清除';
    refreshKeyMeta();
  };
  $('pin').onkeydown = (e) => {
    if (e.key === 'Enter') { keyUnlock(); }
  };
"""
keep = """  $('btn-key-show').onclick = () => {
    const el = $('llm-key');
    el.type = el.type === 'password' ? 'text' : 'password';
  };
"""
if wiring not in s:
    print("FAIL: wiring block not found verbatim")
    sys.exit(1)
s = s.replace(wiring, keep, 1)

# Two calls left over: one on connect, one at the end of wire().
for line in ("    refreshKeyMeta();\n", "  refreshKeyMeta();\n"):
    s = s.replace(line, "", 1)

if 'keystore' in s or 'refreshKeyMeta' in s or 'MAX_ATTEMPTS' in s:
    import re
    for m in re.finditer(r'.*(keystore|refreshKeyMeta|MAX_ATTEMPTS|'
                         r'isValidPin|MIN_PIN_DIGITS).*', s):
        print("LEFTOVER: %s" % m.group(0).strip())
    sys.exit(1)

open(P, 'w', encoding='utf-8').write(s)
print("removed %d bytes" % (len(orig) - len(s)))

