input.newStr:
/* Four columns, packed rather than aligned in rows.
 *
 * A row grid was the obvious thing and it wasted a lot of screen: the cards
 * differ in height by a factor of three (the preview with its image against
 * "Wi-Fi 状态" with one button), and in a row grid every card in a row leaves
 * the difference blank.  Multi-column flow lets a short card sit directly under
 * the one above it.
 *
 * The cost is reading order: cards fill top-to-bottom in the first column, then
 * the next.  That is acceptable here because the cards are independent panels
 * rather than steps in a sequence.
 */

#cards {
  columns: 4;
  column-gap: 7px;
  padding: 7px;
  max-height: 64vh;
  min-height: 0;
  overflow: auto;
}

#cards .card {
  /* Splitting a card across a column boundary would put half its controls at
   * the top of the next column, which is worse than a ragged bottom edge. */
  break-inside: avoid;
  margin: 0 0 7px;
}

